#!/usr/bin/env python3
"""Execute entire original Options preferences with real Fumen notifier and Undo queue."""
import argparse,subprocess,tempfile,json,hashlib
from pathlib import Path
p=argparse.ArgumentParser()
for k in ['editor-root','reference-root','dotnet','output']:p.add_argument('--'+k,type=Path,required=True)
a=p.parse_args();pin='48e18f71655d0f0d86144c63239331833501fda2';fp='0fe292f9c0ef70fb77d61cb54316a7e78dbf3c89'
for path,rev in [(a.editor_root,pin),(a.reference_root/'Fumen',fp)]:assert subprocess.check_output(['git','-C',str(path),'rev-parse','HEAD'],text=True).strip()==rev
source=subprocess.check_output(['git','-C',str(a.editor_root),'show',pin+':StepManiaEditor/Preferences/PreferencesOptions.cs'],text=True,encoding='utf-8-sig')
adapter=r'''using System.Text.Json;using Fumen;using StepManiaEditor;
namespace StepManiaEditor {class Preferences {public static Preferences Instance=new();public PreferencesOptions PreferencesOptions=new();}class Observer:Fumen.IObserver<PreferencesOptions>{public List<string> Events=[];public void OnNotify(string id,PreferencesOptions p,object payload)=>Events.Add(id);}}
class Program {
static void Mutate(PreferencesOptions p){p.RecentFilesHistorySize=7;p.DefaultStepsType=Fumen.Converters.SMCommon.ChartType.dance_double;p.DefaultDifficultyType=Fumen.Converters.SMCommon.ChartDifficultyType.Beginner;p.StartupStepGraphs=[Fumen.Converters.SMCommon.ChartType.dance_single];p.OpenLastOpenedFileOnLaunch=false;p.NewSongSyncOffset=.015;p.OpenSongSyncOffset=.003;p.UseCustomDpiScale=true;p.DpiScale=1.5;p.SuppressExternalSongModificationNotification=true;p.SuppressUpdateNotification=true;p.SuppressExternalPackModificationNotification=true;p.SuppressOpusCodecUsageNotification=true;p.HideSongBackground=true;p.StepColorMethodValue=PreferencesOptions.StepColorMethod.Beat;p.ResetLayout=PreferencesOptions.Layout.Expanded;p.BackgroundImageSize=PreferencesOptions.BackgroundImageSizeMode.Window;p.RenderNotes=false;p.RenderMarkers=false;p.RenderRegions=false;p.RenderMiscEvents=false;p.MiscEventAreaWidth=123;p.MaxMarkersToDraw=9;p.MaxEventsToDraw=10;p.MaxRateAlteringEventsToProcessPerFrame=11;p.MiniMapMaxNotesToDraw=12;p.UndoHistorySize=32;}
static void Main(){var factory=new PermissiveEnumJsonConverterFactory();PreferencesOptions.RegisterDefaultsForInvalidEnumValues(factory);var options=new JsonSerializerOptions{IncludeFields=true};options.Converters.Add(factory);var output=new List<object>();foreach(var json in JsonSerializer.Deserialize<string[]>("""["{}","{\"ShowOptionsWindow\":true}","{\"RecentFilesHistorySize\":-3,\"UndoHistorySize\":0,\"OpenSongSyncOffset\":-1,\"DpiScale\":20,\"StepColorMethodValue\":\"future\",\"BackgroundImageSize\":999}","{\"BackgroundImageSize\":1}","{\"BackgroundImageSize\":\"1\"}","{\"BackgroundImageSize\":\"2\"}","{\"BackgroundImageSize\":\"future\"}","{\"BackgroundImageSize\":true}","{\"BackgroundImageSize\":null}","{\"BackgroundImageSize\":\"ChartArea, Window\"}"]""")){var p=JsonSerializer.Deserialize<PreferencesOptions>(json,options);Preferences.Instance.PreferencesOptions=p;var normalized=JsonSerializer.SerializeToElement(p,options);var usingDefaultsBefore=p.IsUsingDefaults();var o=new Observer();p.AddObserver(o);Mutate(p);var changed=JsonSerializer.SerializeToElement(p,options);var notifications=o.Events.ToArray();o.Events.Clear();Mutate(p);var duplicateNotifications=o.Events.ToArray();p.RestoreDefaults();var restored=JsonSerializer.SerializeToElement(p,options);var restoreNotifications=o.Events.ToArray();o.Events.Clear();ActionQueue.Instance.Undo();var undone=JsonSerializer.SerializeToElement(p,options);var undoNotifications=o.Events.ToArray();o.Events.Clear();ActionQueue.Instance.Redo();var redone=JsonSerializer.SerializeToElement(p,options);var redoNotifications=o.Events.ToArray();o.Events.Clear();p.RestoreDefaults();var noOpNotifications=o.Events.ToArray();output.Add(new{Input=JsonDocument.Parse(json).RootElement.Clone(),Normalized=normalized,UsingDefaultsBefore=usingDefaultsBefore,Changed=changed,Notifications=notifications,DuplicateNotifications=duplicateNotifications,Restored=restored,RestoreNotifications=restoreNotifications,Undone=undone,UndoNotifications=undoNotifications,Redone=redone,RedoNotifications=redoNotifications,NoOpNotifications=noOpNotifications});ActionQueue.Instance.Clear();}Console.Write(JsonSerializer.Serialize(output));}}
'''
with tempfile.TemporaryDirectory(prefix='audio-preferences-oracle-') as d:
 t=Path(d);(t/'Audio.cs').write_text(source);(t/'Program.cs').write_text(adapter);dll=a.reference_root/'Fumen/Fumen/bin/Release/net10.0/Fumen.dll';(t/'Oracle.csproj').write_text(f'<Project Sdk="Microsoft.NET.Sdk"><PropertyGroup><OutputType>Exe</OutputType><TargetFramework>net10.0</TargetFramework><ImplicitUsings>enable</ImplicitUsings><Nullable>disable</Nullable></PropertyGroup><ItemGroup><Reference Include="Fumen"><HintPath>{dll}</HintPath></Reference></ItemGroup></Project>');subprocess.run([str(a.dotnet),'build',str(t/'Oracle.csproj'),'-c','Release','--nologo','-v','quiet'],check=True);assembly=t/'bin/Release/net10.0/Oracle.dll';result=json.loads(subprocess.check_output([str(a.dotnet),str(assembly)],text=True));sha=hashlib.sha256(assembly.read_bytes()).hexdigest()
a.output.write_text(json.dumps(result,indent=2)+'\n');a.output.with_suffix('.reference.json').write_text(json.dumps({'EditorCommit':pin,'FumenCommit':fp,'SourceSha256':hashlib.sha256(source.encode()).hexdigest(),'AdapterSha256':hashlib.sha256(adapter.encode()).hexdigest(),'AssemblySha256':sha,'FumenAssemblySha256':hashlib.sha256(dll.read_bytes()).hexdigest(),'Scope':'Whole original PreferencesOptions class, all fields including non-resettable budgets/layout; real Fumen observer and Restore/Undo/Redo queue; actual permissive enum converter plus source default registration. No renderer, filesystem, update-service or ActionQueue resize observer simulation.'},indent=2)+'\n');print('Executed',len(result),'whole source Options preferences/notifications/history cases.')
